import {useCallback,useEffect,useState} from 'react';
import {settingHelp} from '../../lib/strategySettingHelp';
import {effectiveExecution} from '../../lib/strategyConfiguration';
type Value=number|string|boolean|null;
type Input={key:string;label:string;value:Value;default:Value;type:string};
type FailSafe={timeframe_minutes:number;consecutive_candles:number;loss_pct:number};
type Profit={partial_sell_pct?:number;gain_pct:number;giveback_pct:number;adverse_candle_failsafe:FailSafe|null};
type Contract={exit_minutes:number|null;contract_policy:string|null};
type Execution=Record<string,Record<string,Exclude<Value,null>>>;
type Configuration={execution_defaults:Execution;execution:Execution;execution_overrides:Execution;policy_warning?:string|null;entry:Input[];revision:string;scope:string;mode:string;native_exit:string;exit_policy:(Profit&{rule:string;replace_native_exit:boolean})|null;selected_contract_timer:Contract|null;entry_editable:boolean;risk:Record<string,number|null>;account_risk:Record<string,number|null>;risk_overrides:Record<string,number|null>;profit_overrides:Profit|null;contract_timer_overrides:Contract|null;contract_editable:boolean};
const executionLabels:Record<string,string>={structural_timeframe_minutes:'Structural exit candle interval (minutes)',partial_sell_pct:'Contracts sold at first target (%)',target_minimum_premium:'Target-price ranking: minimum premium ($)',target_maximum_premium:'Target-price ranking: maximum premium ($)',target_premium:'Target-price ranking: preferred premium ($)',missing_structure_hold_minutes:'Missing chart data fallback (minutes)',minimum_open_interest:'Minimum outstanding contracts',maximum_spread_dollars:'Maximum bid/ask gap ($, 0 means no dollar cap)',minimum_dte:'Earliest expiration (days)',maximum_dte:'Latest expiration (days)',minimum_premium:'Minimum option price ($)',maximum_premium:'Maximum option price ($)',maximum_spread_pct:'Maximum bid/ask spread (fraction)',primary_policy:'How to rank eligible contracts',hold_minutes:'Exit after this many minutes',max_hold_bars:'Maximum completed bars held',legacy_arm_dollars:'Start profit protection at ($ per contract)',legacy_giveback_pct:'Peak profit giveback (%)',partial_gain_pct:'First sale at option gain (%)',final_gain_pct:'Final sale at option gain (%)'};
const contracts=[['closest_otm_150_1000','Closest out-of-the-money'],['nearest_weekly_150_1000','Nearest weekly expiration'],['tightest_spread_150_1000','Smallest bid/ask gap'],['lowest_ask_150_1000','Lowest asking price'],['highest_open_interest_150_1000','Most outstanding contracts'],['highest_volume_150_1000','Most contracts traded'],['target_150_250','Closest to configured target premium']];
export function SettingHelp({name}:{name:string}) {
 const help=settingHelp[name];
 return help?<span className="block text-xs text-ink-muted mt-1 leading-relaxed">
  <span className="block">{help.summary}</span>
  <details className="mt-1"><summary className="cursor-pointer text-brand focus-visible:outline focus-visible:outline-2" aria-label={`Learn more about ${help.label}`}>Learn more</summary>
   <span className="block mt-2 rounded border border-line p-2">{help.detail&&<span className="block mb-1">{help.detail}</span>}<strong>Changing it:</strong> {help.effect}</span>
  </details>
 </span>:null;
}
export function SizingComparison({riskFraction,costPercent}:{riskFraction:number|null|undefined;costPercent:number|null|undefined}) {
 const valid=typeof riskFraction==='number'&&Number.isFinite(riskFraction)&&riskFraction>0&&riskFraction<=1&&typeof costPercent==='number'&&Number.isFinite(costPercent)&&costPercent>0&&costPercent<=100;
 if(!valid)return <aside className="rounded-lg border border-line p-3 mt-3 text-sm"><strong>Which limit sets the quantity?</strong><p>Automatic or incomplete values: the bot must resolve the account limits before a contract count can be shown.</p></aside>;
 const budget=10000*riskFraction!,cap=10000*costPercent!/100;
 const riskCount=Math.floor((budget+1e-8)/201.30),costCount=Math.floor((cap+1e-8)/200),count=Math.min(riskCount,costCount);
 const money=(n:number)=>n.toLocaleString('en-US',{style:'currency',currency:'USD'});
 return <aside className="rounded-lg border border-line p-3 mt-3 text-sm" aria-label="Position size comparison">
 <strong>Which limit sets the quantity?</strong>
 <p className="text-xs text-ink-muted mt-1">Example using the percentages above: $10,000 account, $2 option, $1.30 total buying and selling fees per contract. Not an order estimate.</p>
 <div className="grid sm:grid-cols-2 gap-2 my-2">
 <div className="rounded border border-line p-2"><strong>Risk budget</strong><p>{money(budget)} ÷ $201.30 including fees</p><b>{riskCount} contracts</b></div>
 <div className="rounded border border-line p-2"><strong>Purchase-cost cap</strong><p>{money(cap)} ÷ $200 option cost</p><b>{costCount} contracts</b></div>
 </div>
 <p className="font-semibold">{count} contracts: {riskCount===costCount?'both limits tie':riskCount<costCount?'risk budget is the limit':'purchase-cost cap is the limit'}.</p>
 <p className="text-xs text-ink-muted">{money(count*200)} in options + {money(count*1.30)} in modeled fees = {money(count*201.30)} budgeted. Actual prices, configured fees and account checks can change the quantity. Editing percentages previews changes; it does not save them.</p>
 </aside>;
}
export function LiveSizingPreview({strategy,ticker,version,scope}:{strategy:string;ticker:string;version:string;scope:string}) {
 const [result,setResult]=useState<Record<string,any>|null>(null);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [refreshKey,setRefreshKey]=useState(0);
 useEffect(()=>{let cancelled=false;let timer:ReturnType<typeof setTimeout>;const controller=new AbortController();setResult(null);setError('');
 async function refresh(){if(document.hidden){timer=setTimeout(refresh,15000);return;}setBusy(true);try{
 const q=new URLSearchParams({version,scope});const r=await fetch(`/api/settings/strategies/${encodeURIComponent(strategy)}/${encodeURIComponent(ticker)}/sizing-preview?${q}`,{credentials:'include',signal:controller.signal});const d=await r.json();if(!r.ok)throw new Error(d.detail||'Preview unavailable');if(!cancelled){setResult(d);setError('');}
 }catch(e){if(!cancelled){setResult(null);setError((e as Error).message);}}finally{if(!cancelled){setBusy(false);timer=setTimeout(refresh,15000);}}}
 void refresh();return()=>{cancelled=true;controller.abort();clearTimeout(timer);};},[strategy,ticker,version,scope,refreshKey]);
 const dollars=(n:number)=>n.toLocaleString('en-US',{style:'currency',currency:'USD'});
 return <aside className="rounded-lg border border-line p-3 mt-3 space-y-2" aria-label="Actual account sizing preview"><strong>Your account and option price</strong>
 <p className="text-xs text-ink-muted">Automatically uses the option the bot is considering for this strategy and ticker. Checks every 15 seconds while this page is visible. Saved settings only.</p>
 <button type="button" className="btn btn-ghost" disabled={busy} onClick={()=>setRefreshKey(n=>n+1)}>{busy?'Checking the bot’s current contract...':'Refresh preview'}</button>
 {result?.status==='waiting'&&<p role="status" className="text-sm">{result.reason}</p>}
 {error&&<p role="alert" className="text-sm text-red-600">{error}</p>}
 {result?.status==='ready'&&<div role="status" className="space-y-2 text-sm"><p className="text-xs">{result.selection_stage} · Setup {new Date(result.observed_at).toLocaleTimeString()}</p><p>{result.mode} account: <strong>{dollars(result.balance)}</strong> · {result.symbol}</p><p>Ask {dollars(result.ask)} → entry cushion included: {dollars(result.maximum_entry)} per share. Buying and selling fees: {dollars(result.fees_per_contract)} per contract.</p>
 <div className="grid sm:grid-cols-2 gap-2"><p className="border border-line rounded p-2">Risk budget: {dollars(result.risk_budget)}<br/><strong>{result.risk_contracts} contracts including fees</strong></p><p className="border border-line rounded p-2">Purchase-cost cap: {dollars(result.purchase_cap)}<br/><strong>{result.cost_contracts} contracts</strong></p></div>
 <p className="font-semibold">Up to {result.contracts} contracts. {result.limiting} sets the limit.</p><p>Total budget including fees: {dollars(result.total_with_fees)}.</p>
 <p className="text-xs text-ink-muted">Checked {new Date(result.as_of).toLocaleString()}. Quote was {Math.round(result.quote_age_seconds)} seconds old. Refresh for a new estimate. {result.notice}</p></div>}
 </aside>;
}
export function StrategyConfiguration({strategy,ticker,version,embedded=false}:{strategy:string;ticker:string;version:string;embedded?:boolean}){
 const [data,setData]=useState<Configuration|null>(null);const [values,setValues]=useState<Record<string,Value>>({});const [risk,setRisk]=useState<Record<string,number|null>>({});const [profit,setProfit]=useState<Profit|null>(null);const [contract,setContract]=useState<Contract|null>(null);const [execution,setExecution]=useState<Execution>({});const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [saved,setSaved]=useState(false);const [confirmSave,setConfirmSave]=useState(false);
 const url=`/api/settings/strategies/${encodeURIComponent(strategy)}/${encodeURIComponent(ticker)}/configuration`;
 const accept=useCallback((d:Configuration)=>{setData(d);setValues(Object.fromEntries(d.entry.map(f=>[f.key,f.value])));setRisk(d.risk_overrides);setProfit(d.profit_overrides);setContract(d.contract_timer_overrides);setExecution(d.execution_overrides);},[]);
 const load=useCallback(async()=>{setBusy(true);setError('');try{const r=await fetch(`${url}?version=${encodeURIComponent(version)}`,{credentials:'include'});const d=await r.json();if(!r.ok)throw new Error(d.detail||'Could not load configuration');accept(d);}catch(e){setError((e as Error).message);}finally{setBusy(false);}},[url,version,accept]);
 async function save(){if(!data)return;setConfirmSave(false);setBusy(true);setError('');setSaved(false);try{const r=await fetch(url,{method:'PUT',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({version,scope:data.scope,revision:data.revision,entry:values,risk,profit,contract_timer:contract,execution})});const d=await r.json();if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:'Check the settings and try again.');accept(d);setSaved(true);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 const activeProfit=profit??data?.exit_policy;
 const chosen=contract??data?.selected_contract_timer;
 const effective:Execution=data?effectiveExecution(data.execution_defaults,execution,chosen,data.exit_policy?.replace_native_exit):{};
 const timerActive=effective.native_exit?.hold_minutes!=null;
 function changeExecution(section:string,key:string,value:Exclude<Value,null>){
  setExecution({...execution,[section]:{...(section==='contract'?effective.contract:{}),...execution[section],[key]:value}});setSaved(false);
 }
 function clearTimer(){
  const next={...execution,native_exit:{...execution.native_exit}};delete next.native_exit.hold_minutes;setExecution(next);
  setContract({contract_policy:chosen?.contract_policy??null,exit_minutes:null});setSaved(false);
 }


 function changeProfit(key:'gain_pct'|'giveback_pct'|'partial_sell_pct',value:number){if(activeProfit)setProfit({partial_sell_pct:activeProfit.partial_sell_pct??50,gain_pct:activeProfit.gain_pct,giveback_pct:activeProfit.giveback_pct,adverse_candle_failsafe:activeProfit.adverse_candle_failsafe??null,[key]:value});setSaved(false);}
 function changeFailSafe(value:FailSafe|null){if(activeProfit)setProfit({partial_sell_pct:activeProfit.partial_sell_pct??50,gain_pct:activeProfit.gain_pct,giveback_pct:activeProfit.giveback_pct,adverse_candle_failsafe:value});setSaved(false);}
 useEffect(()=>{if(embedded)void load();},[embedded,load]);
 const content=<>

 {busy&&<p role="status">Loading or saving...</p>}{error&&<p role="alert" className="text-red-600">{error} <button className="btn btn-ghost" onClick={load}>Reload saved settings</button></p>}
 {data&&<div className="space-y-4 pt-3"><p className="text-xs text-ink-muted">{ticker} · {data.mode} · Version {version}. Changes apply to future setups. Opening this panel changes nothing.</p>
 {data.policy_warning&&<p role="alert" className="text-amber-700">{data.policy_warning} Showing the newly assigned exit. New entries remain stopped for this configuration until you save.</p>}<section><h5 className="font-semibold">Entry checks</h5><p className="text-xs text-ink-muted">These decide when a setup qualifies. Expand a setting to learn more.</p>{!data.entry_editable&&<p>These entry inputs are still fixed in the strategy code. Editing is not connected yet.</p>}<div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mt-2">{data.entry.map(f=><label className="text-sm" key={f.key}>{settingHelp[f.key]?.label??f.label}{f.type==='boolean'?<input className="ml-2" type="checkbox" checked={Boolean(values[f.key])} onChange={e=>{setValues({...values,[f.key]:e.target.checked});setSaved(false);}}/>:<input className="input w-full mt-1" type={f.type} step={f.type==='number'?'any':undefined} value={String(values[f.key]??'')} onChange={e=>{setValues({...values,[f.key]:f.type==='number'?Number(e.target.value):f.type==='date'&&!e.target.value?null:e.target.value});setSaved(false);}}/>}<SettingHelp name={f.key}/><span className="block text-xs text-ink-muted mt-1">Standard value: {f.default==null?'No date restriction':String(f.default)}{f.type==='time'?' Eastern':''}</span></label>)}</div></section>
 <section><h5 className="font-semibold">Position size</h5><p className="text-xs text-ink-muted">Account loss limits and buying-power checks still apply. Contract count budgets the full option cost plus modeled buying and selling fees. Stops do not increase the quantity.</p><div className="grid sm:grid-cols-2 gap-3 mt-2">{[['risk_per_trade','Risk per trade (%)',100],['max_position_dollars_pct','Maximum position cost (% of account)',1]].map(([key,label,multiplier])=>{const k=String(key),scale=Number(multiplier),v=k in risk?risk[k]:data.account_risk[k];return <label key={k} className="text-sm">{settingHelp[k]?.label??label}<input type="number" step="any" className="input w-full" value={v==null?'':v*scale} placeholder="Account default" onChange={e=>{setRisk({...risk,[k]:e.target.value===''?null:Number(e.target.value)/scale});setSaved(false);}}/><button className="text-xs" onClick={()=>{const next={...risk};delete next[k];setRisk(next);setSaved(false);}}>Use account default</button><SettingHelp name={k}/></label>;})}</div><LiveSizingPreview key={`${data.scope}:${data.revision}`} strategy={strategy} ticker={ticker} version={version} scope={data.scope}/><details className="mt-2"><summary className="cursor-pointer text-sm">See the $10,000 example</summary><SizingComparison riskFraction={risk.risk_per_trade??data.account_risk.risk_per_trade} costPercent={risk.max_position_dollars_pct??data.account_risk.max_position_dollars_pct}/></details></section>
 <section><h5 className="font-semibold">Exit rules</h5>{activeProfit&&data.exit_policy?.rule==='trend_partial_profit'?<><p>Sell part at the first target, then protect the remaining profit.</p><div className="grid sm:grid-cols-2 gap-3 mt-2"><label>{settingHelp.partial_sell_pct.label}<input className="input w-full" type="number" min="0.01" max="99.99" step="any" value={activeProfit.partial_sell_pct??50} onChange={e=>changeProfit('partial_sell_pct',Number(e.target.value))}/><SettingHelp name="partial_sell_pct"/></label><label>{settingHelp.gain_pct.label}<input className="input w-full" type="number" step="any" value={activeProfit.gain_pct} onChange={e=>changeProfit('gain_pct',Number(e.target.value))}/><SettingHelp name="gain_pct"/></label><label>{settingHelp.giveback_pct.label}<input className="input w-full" type="number" step="any" value={activeProfit.giveback_pct} onChange={e=>changeProfit('giveback_pct',Number(e.target.value))}/><SettingHelp name="giveback_pct"/></label></div><label className="block mt-3"><input type="checkbox" checked={!!activeProfit.adverse_candle_failsafe} onChange={e=>changeFailSafe(e.target.checked?{timeframe_minutes:5,consecutive_candles:3,loss_pct:10}:null)}/> Use the candle-and-loss safety exit before profit activation</label><p className="text-xs text-ink-muted">On requires both a run of candles against the trade and the option loss below. Off removes this extra exit. Other active safety rules remain.</p>{activeProfit.adverse_candle_failsafe&&<div className="grid sm:grid-cols-2 gap-3 mt-2"><label>{settingHelp.timeframe_minutes.label}<select className="input w-full" value={activeProfit.adverse_candle_failsafe.timeframe_minutes} onChange={e=>changeFailSafe({...activeProfit.adverse_candle_failsafe!,timeframe_minutes:Number(e.target.value)})}>{[1,2,3,4,5,10,15,20,30,60].map(n=><option key={n} value={n}>{n} minute{n===1?'':'s'}</option>)}</select><SettingHelp name="timeframe_minutes"/></label><label>{settingHelp.consecutive_candles.label}<input className="input w-full" type="number" value={activeProfit.adverse_candle_failsafe.consecutive_candles} onChange={e=>changeFailSafe({...activeProfit.adverse_candle_failsafe!,consecutive_candles:Number(e.target.value)})}/><SettingHelp name="consecutive_candles"/></label><label>{settingHelp.loss_pct.label}<input className="input w-full" type="number" step="any" value={activeProfit.adverse_candle_failsafe.loss_pct} onChange={e=>changeFailSafe({...activeProfit.adverse_candle_failsafe!,loss_pct:Number(e.target.value)})}/><SettingHelp name="loss_pct"/></label><p className="text-xs col-span-full">Both conditions must be met. This protection turns off at +{activeProfit.gain_pct}% profit.</p></div>}</>:<p>{data.native_exit}</p>}{data.exit_policy?.replace_native_exit===true&&<p className="text-xs mt-2">Original timer replaced. Safety exits and end-of-day exits still apply.</p>}</section>
 {Object.entries(effective).map(([section,fields])=>Object.keys(fields).length>0&&<section key={section}><h5 className="font-semibold">{section==='contract'?'Option contract filters':'Original exit settings'}</h5><p className="text-xs text-ink-muted">{section==='contract'?'These choose which options the bot can buy. Prices are per share.':'These control the original exit rule. Account safety and end-of-day exits still apply.'}</p><div className="grid sm:grid-cols-2 gap-3 mt-2">{Object.entries(fields).filter(([key])=>section!=='native_exit'||!timerActive||key==='hold_minutes'||key.startsWith('legacy_')).map(([key,value])=>{const actual=value;function change(v:Exclude<Value,null>){changeExecution(section,key,v);}return <label key={key} className="text-sm">{settingHelp[key]?.label??executionLabels[key]??key.replaceAll('_',' ')}{typeof value==='string'?<select className="input w-full" value={String(actual)} onChange={e=>change(e.target.value)}>{!contracts.some(([v])=>v===actual)&&<option value={String(actual)}>Current strategy ranking</option>}{contracts.map(([v,label])=><option key={v} value={v}>{label}</option>)}</select>:<input className="input w-full" type="number" step="any" value={Number(actual)} onChange={e=>change(Number(e.target.value))}/>}<SettingHelp name={key}/></label>;})}</div></section>)}

 {data.contract_editable&&!data.exit_policy?.replace_native_exit&&data.execution_defaults.native_exit?.hold_minutes==null&&<label className="block text-sm"><input type="checkbox" checked={timerActive} onChange={e=>{if(e.target.checked)changeExecution('native_exit','hold_minutes',30);else clearTimer();}}/> Use a time limit instead of the original exit<p className="text-xs text-ink-muted">When selected, the minutes above replace the original chart exit. Safety exits and session close still apply.</p></label>}
 {timerActive&&<p className="text-xs text-ink-muted">The time limit shown above is the one execution will use. Chart-exit parameters that this timer replaces are hidden.</p>}


 <button className="btn btn-primary" disabled={busy} onClick={()=>setConfirmSave(true)}>Save {ticker} configuration</button>{confirmSave&&<div className="rounded border p-3" role="group" aria-label="Confirm configuration"><p>Save these settings for new {ticker} setups in this {data.mode} account? Existing positions keep their entry-time exit.</p><button className="btn btn-primary" disabled={busy} onClick={save}>Confirm save</button><button className="btn btn-ghost" onClick={()=>setConfirmSave(false)}>Cancel</button></div>}{saved&&<p role="status">Saved for future setups. Strategy switches and existing positions were not changed.</p>}</div>}</>;
 return embedded ? <div>{content}</div> : <details className="mt-3" onToggle={e=>{if(e.currentTarget.open&&!data&&!busy)void load();}}><summary className="cursor-pointer font-semibold">Configure {ticker}</summary>{content}</details>;
}
